      fetchPriceCents: vi.fn().mockResolvedValue(500),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const result = await cart.checkout({ priceFetcher, inventoryChecker, asyncTaxProvider });
    // refreshed subtotal = 500 * 2 = 1000, tax = floor(1000 * 0.0875) = 87
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.totals.taxCents).toBe(87);
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const sut = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [999999, 0],
    [-500, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(sut.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([[-1], [101], [NaN], [Infinity], [-Infinity]])(
      "rejects invalid percent: %s",
      (percent) => {
        expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      },
    );

    it.each([[0], [50], [100]])("accepts valid percent: %s", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it.each([
      [10, 1000, 100],
      [50, 1000, 500],
      [100, 1000, 1000],
      [0, 1000, 0],
      [33, 100, 33],
      [33, 101, 33], // floor(101 * 33 / 100) = floor(33.33) = 33
      [15, 999, 149], // floor(999 * 15 / 100) = floor(149.85) = 149
    ])(
      "%i%% off subtotal %i = discount %i",
      (percent, subtotal, expected) => {
        const sut = new PercentageDiscountPolicy(percent);
        expect(sut.computeDiscountCents(subtotal)).toBe(expected);
      },
    );

    it("returns 0 for zero subtotal", () => {
      const sut = new PercentageDiscountPolicy(50);
      expect(sut.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const sut = new PercentageDiscountPolicy(50);
      expect(sut.computeDiscountCents(-100)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([[-1], [-100], [1.5], [NaN]])(
      "rejects invalid amountCents: %s",
      (amount) => {
        expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
      },
    );

    it.each([[0], [100], [999999]])("accepts valid amountCents: %s", (amount) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns amount when subtotal exceeds it", () => {
      const sut = new FixedAmountDiscountPolicy(500);
      expect(sut.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when amount exceeds subtotal", () => {
      const sut = new FixedAmountDiscountPolicy(500);
      expect(sut.computeDiscountCents(300)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const sut = new FixedAmountDiscountPolicy(500);
      expect(sut.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const sut = new FixedAmountDiscountPolicy(500);
      expect(sut.computeDiscountCents(-100)).toBe(0);
    });

    it("returns 0 when amountCents is 0", () => {
      const sut = new FixedAmountDiscountPolicy(0);
      expect(sut.computeDiscountCents(1000)).toBe(0);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums independent policy results", () => {
      const sut = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // subtotal=1000: 10% = 100, fixed = 200, sum = 300
      expect(sut.computeDiscountCents(1000)).toBe(300);
    });

    it("can exceed subtotal (clamped later by Cart)", () => {
      const sut = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "sum",
      );
      // Each returns min(600, 1000) = 600, sum = 1200 > 1000
      expect(sut.computeDiscountCents(1000)).toBe(1200);
    });

    it("returns 0 for zero subtotal", () => {
      const sut = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(sut.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const sut = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(sut.computeDiscountCents(-500)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const sut = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(sut.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      const sut = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // subtotal=1000: 10% of 1000 = 100, remaining = 900, fixed min(200, 900) = 200
      // total discount = 300
      expect(sut.computeDiscountCents(1000)).toBe(300);
    });

    it("ordering matters in chain mode", () => {
      // Large fixed first then percentage on remainder
      const sut = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(800), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // subtotal=1000: fixed min(800, 1000) = 800, remaining = 200, 50% of 200 = 100
      // total = 900
      expect(sut.computeDiscountCents(1000)).toBe(900);
    });

    it("caps each step to remaining subtotal", () => {
      const sut = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(800), new FixedAmountDiscountPolicy(800)],
        "chain",
      );
      // subtotal=1000: first = min(800, 1000) = 800, remaining = 200, second = min(800, 200) = 200
      // total = 1000
      expect(sut.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const sut = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(sut.computeDiscountCents(0)).toBe(0);
    });
  });
});

