describe("WeightBasedShippingCalculator", () => {
  const brackets = [
    { upToGrams: 500, costCents: 300 },
    { upToGrams: 1000, costCents: 600 },
    { upToGrams: 5000, costCents: 1200 },
  ];

  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: 1.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () => new WeightBasedShippingCalculator(brackets, -1),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () => new WeightBasedShippingCalculator(brackets, 10.5),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const sut = new WeightBasedShippingCalculator(brackets);

    it("returns 0 for empty cart", () => {
      expect(sut.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      const line: CartLine = {
        product: { id: "a", name: "A", unitPriceCents: 100 },
        quantity: 3,
      };
      expect(sut.computeShippingCents([line], 1000)).toBe(0);
    });

    it("selects first bracket (weight exactly at boundary)", () => {
      // 500g exactly = first bracket
      expect(sut.computeShippingCents([makeLine("a", 500, 1)], 1000)).toBe(300);
    });

    it("selects first bracket (weight below boundary)", () => {
      expect(sut.computeShippingCents([makeLine("a", 200, 1)], 1000)).toBe(300);
    });

    it("selects second bracket (weight just over first boundary)", () => {
      expect(sut.computeShippingCents([makeLine("a", 501, 1)], 1000)).toBe(600);
    });

    it("selects second bracket (weight at second boundary)", () => {
      expect(sut.computeShippingCents([makeLine("a", 1000, 1)], 1000)).toBe(600);
    });

    it("selects third bracket (weight between second and third)", () => {
      expect(sut.computeShippingCents([makeLine("a", 2000, 1)], 1000)).toBe(1200);
    });

    it("uses heaviest bracket cost as overflow default", () => {
      // Weight > 5000 with no overflowCostCents
