import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const sut = new NoTaxCalculator();

  it.each([
    [0, "US"],
    [1000, "US"],
    [5000, "FR"],
    [-100, "GB"],
  ])("computeTaxCents(%i, %s) returns 0", (taxable, region) => {
    expect(sut.computeTaxCents(taxable, region)).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it("rejects defaultRate below 0", () => {
      expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
    });

    it("rejects defaultRate above 1", () => {
      expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
    });

    it("rejects NaN defaultRate", () => {
      expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
    });

    it("rejects rate above 1 in rates map", () => {
      expect(() => new RegionalTaxCalculator({ US: 1.5 })).toThrow(RangeError);
    });

    it("rejects negative rate in rates map", () => {
      expect(() => new RegionalTaxCalculator({ US: -0.1 })).toThrow(RangeError);
    });

    it("rejects NaN rate in rates map", () => {
      expect(() => new RegionalTaxCalculator({ US: NaN })).toThrow(RangeError);
    });

    it("accepts boundary rates 0 and 1", () => {
      expect(() => new RegionalTaxCalculator({ US: 0, FR: 1 }, 0.5)).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const sut = new RegionalTaxCalculator(
      { "US-CA": 0.0875, FR: 0.2 },
      0.05,
    );

    it("uses region-specific rate", () => {
      // 1000 * 0.0875 = 87.5, floor = 87
      expect(sut.computeTaxCents(1000, "US-CA")).toBe(87);
    });

    it("uses default rate for unknown region", () => {
      // 1000 * 0.05 = 50
      expect(sut.computeTaxCents(1000, "DE")).toBe(50);
    });

    it("floors the result", () => {
      // 999 * 0.2 = 199.8, floor = 199
      expect(sut.computeTaxCents(999, "FR")).toBe(199);
    });

    it("returns 0 for zero taxable", () => {
      expect(sut.computeTaxCents(0, "US-CA")).toBe(0);
    });

    it("returns 0 for negative taxable", () => {
      expect(sut.computeTaxCents(-500, "US-CA")).toBe(0);
    });

    it("returns 0 when defaultRate is 0 and region is unknown", () => {
      const zeroDefault = new RegionalTaxCalculator({ US: 0.1 }, 0);
      expect(zeroDefault.computeTaxCents(1000, "XX")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("computes tax using provider rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const sut = new AsyncTaxCalculator(provider);
    // 1000 * 0.1 = 100
    expect(await sut.computeTaxCents(1000, "US")).toBe(100);
    expect(provider.getRate).toHaveBeenCalledWith("US");
  });

  it("floors result", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const sut = new AsyncTaxCalculator(provider);
    // 999 * 0.0875 = 87.4125, floor = 87
    expect(await sut.computeTaxCents(999, "US-CA")).toBe(87);
  });

  it("returns 0 for zero taxable without calling provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const sut = new AsyncTaxCalculator(provider);
    expect(await sut.computeTaxCents(0, "US")).toBe(0);
    expect(provider.getRate).not.toHaveBeenCalled();
  });

  it("returns 0 for negative taxable", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const sut = new AsyncTaxCalculator(provider);
    expect(await sut.computeTaxCents(-100, "US")).toBe(0);
  });

  it("throws RangeError when provider returns rate > 1", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(1.5),
    };
    const sut = new AsyncTaxCalculator(provider);
    await expect(sut.computeTaxCents(1000, "XX")).rejects.toThrow(RangeError);
  });

  it("throws RangeError when provider returns negative rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(-0.1),
    };
    const sut = new AsyncTaxCalculator(provider);
    await expect(sut.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError when provider returns NaN", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(NaN),
    };
    const sut = new AsyncTaxCalculator(provider);
    await expect(sut.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("network failure")),
    };
    const sut = new AsyncTaxCalculator(provider);
    await expect(sut.computeTaxCents(1000, "US")).rejects.toThrow("network failure");
  });
});

describe("totalLineWeightGrams", () => {
  it("sums weight * quantity across lines", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 500 }, quantity: 2 },
      { product: { id: "b", name: "B", unitPriceCents: 200, weightGrams: 300 }, quantity: 3 },
    ];
    // 500*2 + 300*3 = 1900
    expect(totalLineWeightGrams(lines)).toBe(1900);
  });

  it("treats missing weightGrams as 0", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 5 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });

  it("returns 0 for empty array", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });
});

