import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const sut = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(sut.computeShippingCents([makeLine("a", 500, 1)], 1000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(sut.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
    });

    it("accepts 0 for both parameters", () => {
      expect(() => new FlatShippingCalculator(0, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flatCents for non-empty cart below threshold", () => {
      const sut = new FlatShippingCalculator(599, 5000);
      expect(sut.computeShippingCents([makeLine("a", 100, 1)], 4999)).toBe(599);
    });

    it("returns 0 when subtotal equals freeOverCents threshold", () => {
      const sut = new FlatShippingCalculator(599, 5000);
      expect(sut.computeShippingCents([makeLine("a", 100, 1)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds threshold", () => {
      const sut = new FlatShippingCalculator(599, 5000);
      expect(sut.computeShippingCents([makeLine("a", 100, 1)], 10000)).toBe(0);
    });

    it("returns flatCents without threshold", () => {
      const sut = new FlatShippingCalculator(999);
      expect(sut.computeShippingCents([makeLine("a", 100, 1)], 100000)).toBe(999);
    });

    it("returns 0 for empty cart regardless of threshold", () => {
      const sut = new FlatShippingCalculator(500, 2000);
